    @Test void succeededCancellationChildCommitBeforeAckReplaysWithoutAnotherEffect() throws Exception {
        var f=paymentFixture("a-c-success-ack",false);var shipment=paidShipment(f);var unit=shipment.units().getFirst();var accepted=acceptCancellation(f,List.of(Map.of("itemId",unit.orderItemId(),"ordinal",unit.ordinal())),"success-ack");UUID claim=UUID.fromString(accepted.get("claimId").asText()),attempt=UUID.fromString(accepted.get("refundAttemptId").asText());runCancellationJob("REFUND_SUBMIT.v1",attempt);var jobs=context.getBean(com.example.marketplace.platform.api.Jobs.class);UUID id=jdbc.queryForObject("SELECT id FROM marketplace.job WHERE type='REFUND_RESULT_RECORDED.v1' AND cause_key=:cause",Map.of("cause",attempt.toString()),UUID.class);Instant now=jobs.find(id).orElseThrow().nextRunAt().plusSeconds(1);var folder=java.nio.file.Files.createDirectory(java.nio.file.Path.of(System.getenv("A3_EVIDENCE")).resolve("refund-success-ack-"+UUID.randomUUID()));Process first=refundProcess(folder,"first",now,id,"ACK"),second=null;
        try {
            awaitJobCondition(()->java.nio.file.Files.exists(folder.resolve("first-effect"))||!first.isAlive(),"successful result child did not commit before ACK");assertTrue(java.nio.file.Files.exists(folder.resolve("first-effect")),"inspect successful result ACK child log");assertEquals("COMPLETED",jdbc.queryForObject("SELECT state FROM marketplace.claim WHERE id=:id",Map.of("id",claim),String.class));assertEquals("RUNNING",jobs.find(id).orElseThrow().status());var committed=cancellationEffectParticipants();first.destroyForcibly();assertTrue(ContractTiming.awaitProcess(first,10,TimeUnit.SECONDS));second=refundProcess(folder,"restart",now.plusSeconds(31),id,"NORMAL");assertTrue(ContractTiming.awaitProcess(second,40,TimeUnit.SECONDS));assertEquals(0,second.exitValue());assertEquals("SUCCEEDED",jobs.find(id).orElseThrow().status());assertEquals(2,jobs.find(id).orElseThrow().attempts());assertEquals(committed,cancellationEffectParticipants());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_refund_effect WHERE attempt_id=:id",Map.of("id",attempt),Integer.class));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.inventory_restitution_unit WHERE item_id=:i AND ordinal=:o",Map.of("i",unit.orderItemId(),"o",unit.ordinal()),Integer.class));assertEquals(1,jdbc.queryForObject("SELECT submit_calls FROM marketplace.payment_refund_mock WHERE attempt_id=:id",Map.of("id",attempt),Integer.class));assertEquals(1,jdbc.queryForObject("SELECT effects FROM marketplace.payment_refund_mock WHERE attempt_id=:id",Map.of("id",attempt),Integer.class));assertEquals("PAID",orders().find(f.order().orderNumber()).state());
        }finally {if(first.isAlive()){first.destroyForcibly();ContractTiming.awaitProcess(first,10,TimeUnit.SECONDS);}if(second!=null&&second.isAlive()){second.destroyForcibly();ContractTiming.awaitProcess(second,10,TimeUnit.SECONDS);}}
    }

