    @Test void confirmationActualWorkerCrashAndStaleLeaseCannotWrite() throws Exception {
        for(String mode:List.of("ACK","CLAIM")) {var f=paymentFixture("a-b-worker-"+mode,false);var v=paidShipment(f);Instant due=Instant.now().plusSeconds(10).truncatedTo(java.time.temporal.ChronoUnit.MICROS);completeShipment(f,v,due.minusSeconds(604800));var unit=new com.example.marketplace.order.api.OrderConfirmations.Unit(v.units().getFirst().orderItemId(),0);UUID id=confirmationJob(unit,0);var folder=java.nio.file.Files.createDirectory(java.nio.file.Path.of(System.getenv("A3_EVIDENCE")).resolve("confirmation-worker-"+UUID.randomUUID()));Process first=confirmationProcess(folder,"first",due,id,mode),second=null;try {awaitJobCondition(()->java.nio.file.Files.exists(folder.resolve("first-effect"))||!first.isAlive(),"confirmation child did not reach "+mode);assertTrue(java.nio.file.Files.exists(folder.resolve("first-effect")),"inspect preserved child log");if(mode.equals("ACK")) {assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.order_confirmation WHERE order_id=:id",Map.of("id",f.order().id()),Integer.class));first.destroyForcibly();assertTrue(ContractTiming.awaitProcess(first,10,TimeUnit.SECONDS));}else {assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM marketplace.order_confirmation WHERE order_id=:id",Map.of("id",f.order().id()),Integer.class));}second=confirmationProcess(folder,"second",due.plusSeconds(31),id,"NONE");assertTrue(ContractTiming.awaitProcess(second,40,TimeUnit.SECONDS));assertEquals(0,second.exitValue(),"inspect preserved second child log");var result=aftercareState();if(mode.equals("CLAIM")) {java.nio.file.Files.writeString(folder.resolve("first-effect-release"),"release stale worker");assertTrue(ContractTiming.awaitProcess(first,40,TimeUnit.SECONDS));assertEquals(0,first.exitValue());assertTrue(java.nio.file.Files.exists(folder.resolve("first-effect-stale-rejected")));assertEquals(result,aftercareState());}assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.order_confirmation WHERE order_id=:id",Map.of("id",f.order().id()),Integer.class));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.order_lifecycle_event WHERE order_id=:id AND action='CONFIRMED'",Map.of("id",f.order().id()),Integer.class));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.job j JOIN marketplace.order_confirmation c ON j.cause_key=c.id::text WHERE c.order_id=:id AND j.type='ORDER_CONFIRMATION_RECORDED'",Map.of("id",f.order().id()),Integer.class));assertEquals(2,context.getBean(com.example.marketplace.platform.api.Jobs.class).find(id).orElseThrow().attempts());}finally {if(first.isAlive()) {first.destroyForcibly();ContractTiming.awaitProcess(first,10,TimeUnit.SECONDS);}if(second!=null&&second.isAlive()) {second.destroyForcibly();ContractTiming.awaitProcess(second,10,TimeUnit.SECONDS);}}}
    }

    @Test void workerRestartKeepsDurableEffects() throws Exception {
        var folder=java.nio.file.Files.createDirectory(java.nio.file.Path.of(System.getenv("A3_EVIDENCE")).resolve("worker-"+UUID.randomUUID()));
        jdbc.getJdbcTemplate().execute("CREATE TABLE marketplace.worker_probe_effect(cause_key TEXT PRIMARY KEY,effects INTEGER NOT NULL)");
        var clock=new JobClock();var jobs=jobs(clock);var type="process-"+UUID.randomUUID();var command=jobCommand(type,clock.instant());var id=jobs.enqueue(command);
        Process first=workerProcess(folder,"first",clock.instant(),type,id,true);Process second=null;
        try {
            awaitJobCondition(()->java.nio.file.Files.exists(folder.resolve("first-effect.txt"))||!first.isAlive(),"owned worker never reached effect barrier");
            assertTrue(java.nio.file.Files.exists(folder.resolve("first-effect.txt")),"child must commit effect before kill; inspect preserved first.log");
            assertEquals(1,jdbc.queryForObject("SELECT effects FROM marketplace.worker_probe_effect WHERE cause_key=:key",Map.of("key",command.causeKey()),Integer.class));
            assertEquals("RUNNING",jobs.find(id).orElseThrow().status());assertEquals(1,jobs.find(id).orElseThrow().attempts());
            first.destroyForcibly();assertTrue(ContractTiming.awaitProcess(first,10,TimeUnit.SECONDS));assertFalse(first.isAlive());clock.advance(31);
            second=workerProcess(folder,"second",clock.instant(),type,id,false);assertThat(second.pid()).isNotEqualTo(first.pid());assertTrue(ContractTiming.awaitProcess(second,40,TimeUnit.SECONDS));assertEquals(0,second.exitValue(),"inspect preserved second.log");
            assertEquals("SUCCEEDED",jobs.find(id).orElseThrow().status());assertEquals(2,jobs.find(id).orElseThrow().attempts());assertEquals(1,jdbc.queryForObject("SELECT effects FROM marketplace.worker_probe_effect WHERE cause_key=:key",Map.of("key",command.causeKey()),Integer.class));assertTrue(java.nio.file.Files.readString(folder.resolve("completed.txt")).contains("nonweb=true"));
        } finally { if(first.isAlive()) { first.destroyForcibly();ContractTiming.awaitProcess(first,10,TimeUnit.SECONDS); }if(second!=null&&second.isAlive()) { second.destroyForcibly();ContractTiming.awaitProcess(second,10,TimeUnit.SECONDS); } }
    }

